#!/usr/bin/env python3
'''Deterministic CPU model checks for K-SYS-015.'''

from dataclasses import dataclass, field
from fractions import Fraction
from typing import Dict, Iterable, List, Optional, Set, Tuple


class CheckError(Exception):
    pass


def require(cond, msg):
    if not cond:
        raise CheckError(msg)


def effective_cores(visible_cpus, cpuset, quotas):
    allowed = set(cpuset)
    require(allowed.issubset(set(range(visible_cpus))), 'cpuset outside visible')
    caps = [Fraction(len(allowed), 1)]
    for max_us, period_us in quotas:
        require(period_us > 0, 'period must be positive')
        if max_us is not None:
            require(max_us >= 0, 'max must be non-negative')
            caps.append(Fraction(max_us, period_us))
    return min(caps)


def check_budget():
    p_eff = effective_cores(64, range(8), [(400000, 100000), (800000, 100000)])
    require(p_eff == 4, 'child quota should bind')
    p_ancestor = effective_cores(64, range(8), [(400000, 100000), (200000, 100000)])
    require(p_ancestor == 2, 'ancestor quota should bind')
    per_req = Fraction(10, 1000) + Fraction(2, 1000) + Fraction(3, 1000)
    other = Fraction(12, 10)
    demand_200 = per_req * 200 + other
    demand_180 = per_req * 180 + other
    require(demand_200 == Fraction(42, 10), 'demand arithmetic')
    require(demand_200 > p_eff, '200 req/s should exceed quota')
    require(demand_200 <= 64, 'visible cores would falsely accept')
    require(demand_180 <= p_eff, '180 req/s should fit necessary bound')
    return {
        'effective_cores': str(p_eff),
        'demand_at_200': str(demand_200),
        'demand_at_180': str(demand_180),
        'negative_control_detected': True,
    }


def unique_bytes(objects):
    sizes = {}
    for pid, n in objects:
        require(n >= 0, 'negative bytes')
        if pid in sizes:
            require(sizes[pid] == n, 'same physical id has different size')
        else:
            sizes[pid] = n
    return sum(sizes.values())


def check_resident():
    objects = []
    for i in range(512):
        objects.append((('in', i), 65536))
    for i in range(512):
        objects.append((('pre', i), 4096 * 4))
    for q in range(128):
        objects.append((('out', q), 65536))
    total = unique_bytes(objects)
    expected = 48 * 1024 * 1024
    require(total == expected, '48 MiB upper bound')

    shared = [(('ipc', 0), 10), (('ipc', 0), 10), (('out', 0), 5)]
    ref = unique_bytes(shared)
    naive = sum(n for _, n in shared)
    require(ref == 15, 'shared physical bytes counted once')
    require(naive == 25, 'naive double count')
    require(naive != ref, 'negative control for duplicate physical object')
    require(unique_bytes([]) == 0, 'empty live set')

    wait_ms = 5 * 20
    require(wait_ms == 100, 'queue wait arithmetic')
    require(not (wait_ms <= 90), 'deadline should be infeasible')
    naive_wait = 0
    require(naive_wait <= 90, 'ignoring queue would falsely accept')
    return {
        'resident_bytes': total,
        'queue_wait_ms': wait_ms,
        'negative_control_detected': True,
    }


def simulate_control(separate, poll_control, max_steps=20):
    data_q = ['old']
    control_q = []
    if separate:
        control_q.append('cancel')
    else:
        data_q.append('cancel')
    worker_blocked = True
    consumer_waiting = True
    cancel_seen = False
    done = False
    for _ in range(max_steps):
        if separate and poll_control and control_q:
            control_q.pop(0)
            cancel_seen = True
        if consumer_waiting and cancel_seen:
            if data_q and data_q[0] == 'old':
                data_q.pop(0)
            consumer_waiting = False
        if (not consumer_waiting) and worker_blocked and len(data_q) < 1:
            data_q.append('new')
            worker_blocked = False
            done = True
            break
    return done


def check_control():
    require(simulate_control(True, True), 'separate control should make progress')
    require(not simulate_control(True, False), 'not polling control should deadlock')
    require(not simulate_control(False, False), 'shared FIFO should deadlock')
    return {'separate_polling': True, 'negative_controls_detected': True}


@dataclass
class Buffer:
    state: str = 'FREE'
    epoch: int = 0
    writer: Optional[str] = None
    readers: Dict[str, int] = field(default_factory=dict)
    payload: int = 0


def acquire_write(buf, uid, unsafe=False):
    require(buf.state == 'FREE', 'write requires FREE')
    if not unsafe:
        require(not buf.readers, 'write requires no readers')
    buf.state = 'WRITING'
    buf.writer = uid
    buf.payload = 0


def publish(buf, uid):
    require(buf.state == 'WRITING' and buf.writer == uid, 'publish by writer')
    buf.writer = None
    buf.state = 'PUBLISHED'


def acquire_read(buf, uid):
    require(buf.state in ('PUBLISHED', 'READING'), 'read only after publish')
    require(uid not in buf.readers, 'duplicate reader')
    buf.readers[uid] = buf.epoch
    buf.state = 'READING'


def release_read(buf, uid, epoch):
    if buf.readers.get(uid) != epoch:
        return False
    if buf.epoch != epoch:
        return False
    del buf.readers[uid]
    return True


def retire_buf(buf):
    require(buf.state in ('PUBLISHED', 'READING'), 'retire a live buffer')
    buf.state = 'RETIRING'


def recycle_buf(buf, unsafe=False):
    require(buf.state == 'RETIRING', 'recycle a retiring buffer')
    if not unsafe:
        require(not buf.readers, 'readers still active')
    buf.state = 'FREE'
    buf.epoch += 1
    buf.payload = 0


def check_ownership():
    b = Buffer()
    acquire_write(b, 'w1')
    b.payload = 7
    publish(b, 'w1')
    acquire_read(b, 'r1')
    acquire_read(b, 'r2')
    retire_buf(b)
    safe_rejected = False
    try:
        recycle_buf(b)
    except CheckError:
        safe_rejected = True
    require(safe_rejected, 'recycle must wait for readers')
    require(release_read(b, 'r1', 0), 'first reader release')
    safe_rejected = False
    try:
        recycle_buf(b)
    except CheckError:
        safe_rejected = True
    require(safe_rejected, 'one reader remains')
    require(release_read(b, 'r2', 0), 'second reader release')
    recycle_buf(b)
    require(b.epoch == 1 and b.state == 'FREE', 'recycled epoch')
    require(not release_read(b, 'r1', 0), 'late release must not hit new generation')

    u = Buffer()
    acquire_write(u, 'w1')
    publish(u, 'w1')
    acquire_read(u, 'r1')
    retire_buf(u)
    recycle_buf(u, unsafe=True)
    require(u.epoch == 1 and u.readers.get('r1') == 0, 'unsafe recycle keeps stale reader')
    acquire_write(u, 'w2', unsafe=True)
    require(u.state == 'WRITING' and u.readers.get('r1') == 0, 'unsafe overwrite visible')
    require(not release_read(u, 'r1', 0), 'stale ticket rejected after reuse')
    return {'safe_epoch': b.epoch, 'negative_control_detected': True}


def remove_key(s, key):
    if key in s:
        s.remove(key)
        return True
    return False


def can_free(uses, readers, quarantined):
    return not uses and not readers and not quarantined


def check_shutdown():
    uses = {'parse', 'kernel'}
    readers = {'send'}
    quarantined = set()
    require(not can_free(uses, readers, quarantined), 'uses and readers remain')
    require(remove_key(uses, 'parse'), 'parse completion')
    require(not can_free(uses, readers, quarantined), 'kernel and reader remain')
    require(not remove_key(uses, 'parse'), 'duplicate completion ignored')
    require(remove_key(uses, 'kernel'), 'kernel completion')
    require(not can_free(uses, readers, quarantined), 'reader remains')
    require(remove_key(readers, 'send'), 'reader completion')
    require(can_free(uses, readers, quarantined), 'all responsibilities settled')

    uses2 = {'kernel'}
    readers2 = {'send'}
    naive_freed = True
    require(naive_freed and not can_free(uses2, readers2, set()), 'negative control for early free')
    return {'shutdown_release': True, 'negative_control_detected': True}


def child_pipe(drain):
    cap = 4
    units = 10
    written = 0
    drained = 0
    while written < units:
        if written - drained >= cap:
            return {'returncode': None, 'blocked': True, 'captured': drained, 'alive': True}
        written += 1
        if drain:
            drained = written
    return {'returncode': 0, 'blocked': False, 'captured': drained, 'alive': False}


def timeout_effect(kill):
    return {'timeout': True, 'alive': not kill, 'returncode': None}


def check_child_io():
    blocked = child_pipe(False)
    drained = child_pipe(True)
    require(blocked['returncode'] is None and blocked['blocked'], 'wait without drain blocks')
    require(drained['returncode'] == 0 and not drained['blocked'], 'draining finishes')
    require(timeout_effect(False)['alive'], 'timeout alone does not kill')
    require(not timeout_effect(True)['alive'], 'kill then wait can clean up')
    naive_success = True
    require(naive_success and blocked['blocked'], 'negative control for wait-only success claim')
    return {'drained_returncode': drained['returncode'], 'negative_control_detected': True}


def main():
    checks = [
        ('budget', check_budget),
        ('resident', check_resident),
        ('control_queue', check_control),
        ('ownership', check_ownership),
        ('shutdown', check_shutdown),
        ('child_io', check_child_io),
    ]
    for name, fn in checks:
        detail = fn()
        print('CHECK', name, 'OK', detail)
    print('SCOPE: deterministic CPU symbolic model; no real runtime, cgroup, GPU, network or subprocess execution')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
